commits.patch:
diff --git a/libarchive/archive_read_support_format_warc.c b/libarchive/archive_read_support_format_warc.c
index 82adb55..3b20894 100644
--- a/libarchive/archive_read_support_format_warc.c
+++ b/libarchive/archive_read_support_format_warc.c
@@ -754,8 +754,8 @@ warc_read_uri(const char *buf, size_t bsz)
 		return res;
 	}

-	/* Require valid C string representation. */
-	if (memchr(uri, '\0', eol - uri) != NULL)
+	if (uri < eol &&
+	    memchr(uri + 1, '\0', eol - uri - 1) != NULL)
 		return res;

 	res.str = uri;

--- a/libarchive/archive_read_support_format_warc.c
+++ b/libarchive/archive_read_support_format_warc.c
@@ -731,2 +731,3 @@
 	archive_strncpy(str, uri, eol - uri);
+	str->length = eol - uri;
 }
